        "title": "把卫星价格「打下来」：10亿一颗的SAR卫星，他们用土办法做到小几千万",
        "hook": "一颗合成孔径雷达卫星以前10个亿起步——有个团队用网购摄像头、卷尺当天线，把它做成了小几千万。",
        "story": {
          "setup": "11月19日，知乎发布「知乎科学创作者生态图鉴」。天仪空间创始人兼CEO杨峰在活动上分享了一个话题：怎么把卫星的价格打下来。",
          "conflict": "传统的SAR卫星（搭载合成孔径雷达的遥感卫星），过去贵到10亿元起步一颗。对很多想用遥感数据的单位和个人来说，这是道过不去的门槛。",
          "turn": "杨峰团队的做法很「土」：用网购的摄像头、卷尺做的天线、尼龙绳热刀分离——这些看着不专业的东西，把成本压到了小几千万元级别。思路是：非核心环节用成熟廉价方案替代，把钱花在真正影响性能的地方。",
          "open": "这套「把成本打下来」的逻辑，对做制造的小厂同样成立：先分清楚哪些环节决定客户要不要买，哪些只是「看起来专业」，后者大胆用便宜方案。金额为创始人公开分享，属个案，不代表普遍收益。"
        },
