        "title": "\"养老缴满15年就能坐等退休\"是谣言：2030年起最低缴费年限要涨到20年",
        "hook": "\"社保缴满15年就不用再交、坐等退休\"——这句话最近刷屏，可官方辟谣了：信它，到点可能领不到养老金。",
        "story": {
          "setup": "一条\"养老保险缴够15年就可以退休、不用再交钱\"的说法近日在网上流传，福建厦门人社局专门出面辟谣。",
          "conflict": "关键变化很多人没注意：按《国务院关于渐进式延迟法定退休年龄的办法》，从2030年1月1日起，按月领养老金的最低缴费年限，将从15年逐步提高到20年，每年提高6个月。也就是说，这个年限和你的退休时间直接挂钩，不是固定不变的。",
          "turn": "哪三类人尤其要注意？1970年1月及以后出生的男性、1975年1月及以后出生且原55岁退休的女性、1980年1月及以后出生且原50岁退休的女性——只缴满15年并不够，还得继续缴。",
          "open": "在单位上班的，只要没到法定退休年龄，单位依法必须给你参保，\"协商不缴\"的约定违法且无效；灵活就业的可以自己选，但养老金是\"多缴多得、长缴多得\"。"
        },
