          "依据《国务院关于渐进式延迟法定退休年龄的办法》，自2030年1月1日起，按月领取基本养老金最低缴费年限从15年逐步提高到20年，每年提高6个月",
          "三类人群只缴满15年不够：1970年1月及以后出生男性、1975年1月及以后出生且原法定退休年龄55周岁女性、1980年1月及以后出生且原法定退休年龄50周岁女性",
